def H_for(account_desc, desc_norm):
    a = MAP.get(account_desc)
    if not a: return "H_OTHER"
    d = (desc_norm or "").lower()
    for r in a["desc_rules"]:
        kw = [str(k).lower() for k in r.get("keywords", []) if str(k).strip()]
        if kw and any(k in d for k in kw): return r["H"]
    return a["default_H"]

def main():
    src = ROOT/"data"/"review"/"_dump"/"vml_sigs_23.jsonl"
    if not src.exists():
        print("X run: python scripts/dump_sigs_year.py --entity vml --year 23 --inputs-only"); return
    out = ROOT/"data"/"_overrides"/"vml_horizontal.tsv"; out.parent.mkdir(parents=True, exist_ok=True)
    n=0; dist={}
    with out.open("w", encoding="utf-8") as w:
        for line in src.open(encoding="utf-8"):
            line=line.strip()
            if not line: continue
            r=json.loads(line); sig=r["signature"]
            parts=sig.split("|"); desc_norm = parts[2] if len(parts)>=3 else ""
            H=H_for(r.get("account_desc",""), desc_norm)
            w.write(f"{sig}\t{H}\n"); n+=1; dist[H]=dist.get(H,0)+1
    print(f"wrote {out.relative_to(ROOT)}: {n} sigs")
    for h,c in sorted(dist.items(), key=lambda x:-x[1]): print(f"  {h:16s} {c}")

if __name__ == "__main__":
    main()
